/* Buyer tools and boutique services. All state stays on this device. */
window.velourCatalogState={query:'',sort:'featured'};
let compareIds=read('velour-compare',[]);if(!Array.isArray(compareIds))compareIds=[];compareIds=compareIds.filter(id=>products.some(p=>p.id===id)).slice(0,3);
let recentIds=read('velour-recent',[]);if(!Array.isArray(recentIds))recentIds=[];
function buyerStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Браузер не разрешил сохранить изменения.')}}
const toolbar=document.createElement('div');toolbar.className='catalog-tools';toolbar.innerHTML='<label class="catalog-search"><span>⌕</span><input type="search" id="catalogSearch" placeholder="Название, оттенок или фасон" aria-label="Поиск по коллекции"><button id="clearSearch" aria-label="Очистить поиск" hidden>×</button></label><label class="catalog-sort"><span>Сортировать</span><select id="catalogSort" aria-label="Сортировка коллекции"><option value="featured">Выбор VELOUR</option><option value="price-up">Сначала дешевле</option><option value="price-down">Сначала дороже</option><option value="name">По названию</option></select></label>';
$('.filters').before(toolbar);
const compareTray=document.createElement('div');compareTray.className='compare-tray';$('.filters').after(compareTray);
const compareDialog=document.createElement('dialog');compareDialog.id='compareDialog';compareDialog.setAttribute('aria-labelledby','compareTitle');compareDialog.innerHTML='<button class="close" data-close aria-label="Закрыть">×</button><p class="eyebrow">ВЫБИРАЙТЕ В СВОЁМ РИТМЕ</p><h2 id="compareTitle">Искусство сравнения.</h2><div id="compareContents"></div>';document.body.append(compareDialog);
const sizeDialog=document.createElement('dialog');sizeDialog.id='sizeGuideDialog';sizeDialog.setAttribute('aria-labelledby','sizeGuideTitle');sizeDialog.innerHTML='<button class="close" data-close aria-label="Закрыть">×</button><p class="eyebrow">VELOUR / ГИД ПО ПОСАДКЕ</p><h2 id="sizeGuideTitle">Ваш идеальный размер.</h2><p>Ориентировочная таблица российских размеров. Посадка зависит от модели; точные замеры нужно уточнить перед покупкой.</p><div class="size-table-wrap"><table class="size-table"><caption>Обхваты тела в сантиметрах</caption><thead><tr><th>Размер</th><th>Грудь</th><th>Талия</th><th>Бёдра</th></tr></thead><tbody>'+[[40,80,62,86],[42,84,66,90],[44,88,70,94],[46,92,74,98],[48,96,78,102]].map(r=>'<tr>'+r.map((v,i)=>`<${i?'td':'th'}>${v}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</tbody></table></div><p class="size-advice">Измеряйте по самой выступающей части груди и бёдер. Если планируете носить объёмный трикотаж, учитывайте свободную посадку.</p>';document.body.append(sizeDialog);
for(const d of [compareDialog,sizeDialog])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
function syncCompare(){compareIds=compareIds.filter(id=>products.some(p=>p.id===id));$$('[data-compare]').forEach(b=>{const selected=compareIds.includes(b.dataset.compare);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));b.textContent=selected?'✓ В сравнении':'＋ Сравнить модель'});compareTray.hidden=!compareIds.length;compareTray.innerHTML=compareIds.length?`<div><span class="eyebrow">ВАШ ВЫБОР / ${compareIds.length} ИЗ 3</span><p>${compareIds.map(id=>esc(products.find(p=>p.id===id).name)).join(' · ')}</p></div><div><button id="showCompare" ${compareIds.length<2?'disabled':''}>Сравнить модели ↗</button><button id="clearCompare">Очистить</button></div>`:'';if($('#showCompare'))$('#showCompare').onclick=showComparison;if($('#clearCompare'))$('#clearCompare').onclick=()=>{compareIds=[];buyerStore('velour-compare',compareIds);syncCompare()}}
function showComparison(){const selected=compareIds.map(id=>products.find(p=>p.id===id)).filter(Boolean);if(selected.length<2)return;$('#compareContents').innerHTML=`<div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>Модель</th>${selected.map(p=>`<th><h3>${esc(p.name)}</h3><button data-product="${esc(p.id)}">Посмотреть ↗</button></th>`).join('')}</tr></thead><tbody>${[['Цена',p=>money(p.price)],['Фасон',p=>p.category],['Оттенок',p=>p.color],['Размеры',p=>p.sizes]].map(([label,get])=>`<tr><th>${label}</th>${selected.map(p=>`<td>${esc(get(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="payment-disclosure">Модели и цены демонстрационные.</p>`;compareDialog.showModal()}
const boutiqueRender=render;render=function(){boutiqueRender();syncCompare()};
$('#catalogSearch').addEventListener('input',e=>{window.velourCatalogState.query=e.target.value.trim();$('#clearSearch').hidden=!e.target.value;render()});$('#clearSearch').onclick=()=>{$('#catalogSearch').value='';window.velourCatalogState.query='';$('#clearSearch').hidden=true;render();$('#catalogSearch').focus()};$('#catalogSort').onchange=e=>{window.velourCatalogState.sort=e.target.value;render()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-compare]');if(!b)return;const id=b.dataset.compare;if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else if(compareIds.length<3)compareIds.push(id);else{toast('Для сравнения можно выбрать до трёх моделей.');return}buyerStore('velour-compare',compareIds);syncCompare()});
const recentSection=document.createElement('section');recentSection.className='recent-section';recentSection.hidden=true;$('.editorial').before(recentSection);
function renderRecent(){recentIds=recentIds.filter(id=>products.some(p=>p.id===id)).slice(0,5);recentSection.hidden=!recentIds.length;recentSection.innerHTML=`<div class="recent-heading"><div><p class="eyebrow">ПРОДОЛЖИТЕ ЗНАКОМСТВО</p><h2>Вы присматривались.</h2></div><button id="clearRecent">Очистить историю</button></div><div class="recent-models">${recentIds.map(id=>{const p=products.find(p=>p.id===id);return `<button data-product="${esc(id)}"><span>${esc(p.name)}</span><small>${esc(p.color)}</small><strong>${money(p.price)} ↗</strong></button>`}).join('')}</div>`;$('#clearRecent').onclick=()=>{recentIds=[];buyerStore('velour-recent',[]);renderRecent()}}
const boutiqueOpen=openProduct;openProduct=function(id){if(compareDialog.open)compareDialog.close();boutiqueOpen(id);if(!products.some(p=>p.id===id))return;recentIds=[id,...recentIds.filter(x=>x!==id)].slice(0,5);buyerStore('velour-recent',recentIds);renderRecent();$('#productDetail .choose-size-label').insertAdjacentHTML('beforeend',' <button class="size-guide-button" id="sizeGuideButton">Гид по размерам ↗</button>');$('#sizeGuideButton').onclick=()=>sizeDialog.showModal()};
const benefits=document.createElement('section');benefits.className='buyer-privileges';benefits.innerHTML='<div class="privilege-intro"><p class="eyebrow">МАЛЕНЬКИЕ ЗНАКИ ВНИМАНИЯ</p><h2>Больше,<br><em>чем покупка.</em></h2><p>Попробуйте привилегии в демонстрационном заказе.</p></div><div class="privilege-list"><article><span>01</span><div><h3>Знакомство с VELOUR</h3><p>Промокод WELCOME10 уменьшит сумму демо-заказа на 10%.</p><button id="welcomePromo">Применить WELCOME10 ↗</button></div></article><article><span>02</span><div><h3>Красота первого впечатления</h3><p>Выберите подарочную упаковку в корзине — в демо-заказе без доплаты.</p></div></article><article><span>03</span><div><h3>Ваш выбор под рукой</h3><p>Избранное, сравнение и история просмотров сохраняются в этом браузере.</p></div></article></div>';$('.appointment').before(benefits);
$('#welcomePromo').onclick=()=>{buyerStore('velour-promo','WELCOME10');toast('WELCOME10 применён: −10% к сумме демо-заказа.');if(validCart().length){renderCart();$('#cartDialog').showModal()}};
const boutiqueCart=renderCart;renderCart=function(){boutiqueCart();const summary=$('.cart-summary');if(!summary)return;const promo=read('velour-promo','')==='WELCOME10',gift=read('velour-gift',false);const extras=document.createElement('section');extras.className='cart-extras';extras.innerHTML=`<p class="eyebrow">ЗНАКИ ВНИМАНИЯ</p><form id="promoForm"><label for="promoCode">Промокод</label><div class="promo-entry"><input id="promoCode" name="promo" placeholder="WELCOME10" value="${promo?'WELCOME10':''}" maxlength="40" autocomplete="off"><button type="submit">Применить</button></div><p id="promoStatus" role="status">${promo?'WELCOME10 применён — скидка 10%':'Попробуйте WELCOME10: −10% в демо-заказе'}</p></form>${promo?'<button class="remove-promo" id="removePromo">Убрать промокод</button>':''}<label class="gift-option"><input type="checkbox" id="giftWrap" ${gift?'checked':''}><span>Подарочная упаковка<small>Без доплаты в демо-заказе</small></span><span>✧</span></label>`;summary.before(extras);if(promo){const line=document.createElement('div');line.className='discount-line';line.innerHTML='<span>WELCOME10 · −10%</span><span>−'+money(Math.round(cartSubtotal()*.1))+'</span>';summary.querySelector('.cart-grand-total').before(line)}$('#promoForm').onsubmit=e=>{e.preventDefault();const code=$('#promoCode').value.trim().toUpperCase();if(code!=='WELCOME10'){$('#promoStatus').textContent='Промокод не найден. Доступен WELCOME10.';$('#promoStatus').classList.add('invalid');return}buyerStore('velour-promo','WELCOME10');renderCart()};if($('#removePromo'))$('#removePromo').onclick=()=>{buyerStore('velour-promo','');renderCart()};$('#giftWrap').onchange=e=>buyerStore('velour-gift',e.target.checked)};
const boutiquePayment=openPayment;openPayment=function(){boutiquePayment();if(read('velour-gift',false)&&$('#paymentDialog').open){const line=document.createElement('div');line.className='payment-order';line.innerHTML='<span>Подарочная упаковка</span><strong>Включена · 0 ₽</strong>';$('#paymentContents .payment-order').before(line)}};
document.addEventListener('velour:catalog-changed',()=>{syncCompare();renderRecent()});
syncCompare();renderRecent();
const heroLight=document.createElement('div');heroLight.className='hero-cursor-light';heroLight.setAttribute('aria-hidden','true');$('.hero').append(heroLight);if(!reduced&&matchMedia('(pointer:fine)').matches){$('.hero').addEventListener('pointermove',e=>{if(document.body.classList.contains('motion-paused'))return;const r=e.currentTarget.getBoundingClientRect();heroLight.style.setProperty('--light-x',e.clientX-r.left+'px');heroLight.style.setProperty('--light-y',e.clientY-r.top+'px')},{passive:true})}
const livingCaption=document.createElement('div');livingCaption.className='hero-living-caption';livingCaption.setAttribute('aria-hidden','true');livingCaption.innerHTML='<i></i><span>01 / БЛАГОРОДНЫЕ ФАКТУРЫ</span>';$('.hero').append(livingCaption);const captions=['01 / БЛАГОРОДНЫЕ ФАКТУРЫ','02 / ВЫРАЗИТЕЛЬНЫЕ СИЛУЭТЫ','03 / ВАШ ОСОБЕННЫЙ ХАРАКТЕР'];let captionIndex=0;if(!reduced)setInterval(()=>{if(document.hidden||document.body.classList.contains('motion-paused'))return;captionIndex=(captionIndex+1)%captions.length;livingCaption.querySelector('span').textContent=captions[captionIndex]},5000);
